    TMPFLD01_OBJETO VARCHAR(63) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TMPFLD01_SECCION VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
